    if(state.view==='forgot')return `<div class="container"><div class="form-card"><span class="label">RECUPERO</span><h1>Recupera l'accesso.</h1><p>Ti invieremo un collegamento all'email registrata.</p><div class="card"><form id="forgot-form" class="stack"><div class="field"><label for="gd-forgot-email">Email</label><input id="gd-forgot-email" name="email" type="email" required autocomplete="email"></div>${captchaSlot('recover')}<button class="btn btn-dark btn-block" type="submit">Invia collegamento</button></form></div><div class="form-footer">${button('Torna all’accesso','signin','btn-ghost')}</div></div></div>`;
    if(state.view==='reset')return `<div class="container"><div class="form-card"><h1>Nuova password.</h1><div class="card"><form id="reset-form" class="stack"><div class="field"><label for="gd-reset-password">Nuova password (minimo 10 caratteri)</label><input id="gd-reset-password" name="password" type="password" minlength="10" required autocomplete="new-password"></div><button class="btn btn-dark btn-block" type="submit">Aggiorna password</button></form></div></div></div>`;
    if(state.view==='confirm')return `<div class="container"><div class="interstitial"><span class="label">VERIFICA EMAIL</span><h2>Controlla la posta.</h2><p>${e(state.notice||'Abbiamo inviato il messaggio di verifica. Conferma l’indirizzo e poi accedi per continuare.')}</p>${button('Torna all’accesso','signin','btn-dark')}</div></div>`;
